    @tracer.start_as_current_span("tasks.tasks_filters_add")
    def tasks_filters_add(
        self,
        name: str,
        creators: [tuple[str, ...], list[str]] = (),
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ):
        """
        Метод для создания нового фильтра пользователем.
        """
        if isinstance(deadline, str):
            deadline = {"type": "predefined", "predefined": deadline}
        elif deadline is None:
            deadline = None
        elif isinstance(deadline, dict):
            deadline = deadline
        else:
            deadline = {"type": "date", "date": int(deadline.timestamp())}

        return self.post(
            "tasks/filters/add",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": name,
                    "assignees": assignees,
                    "creators": creators,
                    "statuses": statuses,
                    "deadline": deadline,
                    "subscribed": subscribed,
                    "withChanges": withChanges,
                },
            },
        )

    @tracer.start_as_current_span("tasks.tasks_filters_edit")
    def tasks_filters_edit(
        self,
        filter_id: str,
        name: Optional[str] = None,
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ):
        """
        Метод для изменения фильтра пользователем.
        """
        if deadline is None:
            deadline = datetime.now() + timedelta(days=5)
        if filter_id == "c55aef38-7e17-406e-8160-3834f9ff92c3":
            raise ValueError("Cannot delete filter 'All'")
        return self.post(
            "tasks/filters/edit",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "id": filter_id,
                    "name": name,
                    "assignees": assignees,
                    "creators": [self.uin],
                    "statuses": statuses,
                    "deadline": {"type": "predefined", "predefined": deadline}
                    if isinstance(deadline, str)
                    else {"type": "date", "date": int(deadline.timestamp())},
                    "subscribed": subscribed,
                    "withChanges": withChanges,
                },
            },
        )

