    @tracer.start_as_current_span("tasks.tasks_getUserTags")
    def tasks_getUserTags(
        self,
        filter_id: Optional[str] = None,
        page_size: int = 10,
    ):
        """
        Метод для получения списка тегов задач,
        на которые подписан пользователь,
        отсортированный по частоте использования.
        """
        if filter_id is None:
            return self.post(
                "rapi/tasks/getUserTags",
                headers={"Content-Type": "application/json"},
                json={
                    "reqId": self.getReqId(),
                    "aimsid": self.aimsid,
                    "params": {
                        "pageSize": page_size,
                    },
                },
            )
        return self.post(
            "tasks/getUserTags",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "filter_id": filter_id,
                    "pageSize": page_size,
                },
            },
        )

